use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_selected_phase(container.api_selected_phase);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase)
{
  put_selected_phase(selected_phase);
}

/// setter for IN DataPort
pub fn put_selected_phase(value: Drone_Lifecycle_Governor::Lifecycle_Phase)
{
  *extern_api::IN_selected_phase.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_lifecycle_enablement() -> Drone_Lifecycle_Governor::Lifecycle_Enablement
{
  return extern_api::OUT_lifecycle_enablement.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
